      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call lpb_mf_tangent(state, dr, dn, dk1, dk2, dxi, dF, da, dv, hvp_r, hvp_n, hvp_k1, &
                             hvp_k2, hvp_xi, hvp_F, hvp_a, hvp_v, error)
         return
      end if
      if (state%ready < 4) then
         call fatal_error(error, "[lpb_tangent] call lpb_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[lpb_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[lpb_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_tangent] dk1: wrong shape")
         return
      end if
      if (any(shape(dk2) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_tangent] dk2: wrong shape")
         return
      end if
      if (any(shape(dxi) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_tangent] dxi: wrong shape")
         return
      end if
      if (any(shape(dF) /= [npt, nblk])) then
