         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_complex_mf_tangent] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call lpb_complex_mf_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                         dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
                                         dv(:, blk), hvp_r(:, :, blk), hvp_n(:, :, blk), &
                                         hvp_k1(:, blk), hvp_k2(:, blk), hvp_xi(:, blk), &
                                         hvp_F(:, blk), hvp_a(:, blk), hvp_v(:, blk), error)
