   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true; the same for this operator
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine lpb_op1_apply(self, trans, x, y)
      !> Operator
