      end associate
      call gemv(self%c1, x, y)
   end subroutine lpb_op1_apply

   !> Form operator 1 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine lpb_op1_assemble(self, a, error)
      !> Operator
      class(lpb_op1), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      if (allocated(error)) return   ! nothing to allocate; error stays unset
      a = self%c1
   end subroutine lpb_op1_assemble

   !> Form operator 1 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine lpb_op1_assemble_block(self, idx, a, error)
      !> Operator
      class(lpb_op1), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:, :)

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[lpb_op1_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_op1_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%c1(idx, idx)
      a = tmp1
   end subroutine lpb_op1_assemble_block

   !> Apply operator 2 or its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine lpb_op2_apply(self, trans, x, y)
      !> Operator
      class(lpb_op2), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      if (trans) then
         call lpb_op2_apply_t(self, x, y)
      else
         call lpb_op2_apply_n(self, x, y)
      end if
   end subroutine lpb_op2_apply

   !> Apply the transpose of operator 2
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine lpb_op2_apply_t(self, x, y)
      !> Operator
      class(lpb_op2), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp5(self%npt))
      allocate (tmp6(self%npt))
      allocate (tmp7(self%npt))
      allocate (tmp8(self%npt))
      allocate (tmp9(self%npt))
      allocate (tmp10(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp12(self%npt))
      call gemv(self%c3, x, tmp1, trans="t")
      tmp2 = self%a*tmp1
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = x + tmp3
      call gemv(self%c2, tmp4, tmp5, trans="t")
      tmp6 = self%c1*tmp5
      call gemv(self%c5, x, tmp7, trans="t")
      tmp8 = self%a*tmp7
      call gemv(self%c6, tmp8, tmp9)
      tmp10 = 0.15915494309189535_wp*tmp9
      tmp11 = tmp7 + tmp10
      tmp12 = self%c4*tmp11
      y = tmp6 + tmp12
   end subroutine lpb_op2_apply_t

   !> Apply operator 2
   !>
   !> @param[in]  self  operator
   !> @param[in]  x     input vector
   !> @param[out] y     result vector
   subroutine lpb_op2_apply_n(self, x, y)
      !> Operator
      class(lpb_op2), intent(in) :: self
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      real(wp), allocatable :: tmp1(:), tmp2(:), tmp3(:), tmp4(:), tmp5(:), tmp6(:), tmp7(:), &
                               tmp8(:), tmp9(:), tmp10(:), tmp11(:), tmp12(:)

      allocate (tmp1(self%npt))
      allocate (tmp2(self%npt))
      allocate (tmp3(self%npt))
      allocate (tmp4(self%npt))
      allocate (tmp5(self%npt))
      allocate (tmp6(self%npt))
      allocate (tmp7(self%npt))
      allocate (tmp8(self%npt))
      allocate (tmp9(self%npt))
      allocate (tmp10(self%npt))
      allocate (tmp11(self%npt))
      allocate (tmp12(self%npt))
      call gemv(self%c2, x, tmp1)
      tmp2 = self%a*tmp1
      call gemv(self%c3, tmp2, tmp3)
      tmp4 = (-0.15915494309189535_wp)*tmp3
      tmp5 = tmp1 + tmp4
      tmp6 = self%c1*tmp5
      call gemv(self%c6, x, tmp7, trans="t")
      tmp8 = self%a*tmp7
      tmp9 = 0.15915494309189535_wp*tmp8
      tmp10 = x + tmp9
      call gemv(self%c5, tmp10, tmp11)
      tmp12 = self%c4*tmp11
      y = tmp6 + tmp12
   end subroutine lpb_op2_apply_n

   !> Form operator 2 as a dense matrix
   !>
   !> @param[in]  self  operator
   !> @param[out] a     matrix of shape (npt, npt)
   !> @param[out] error  error handling; allocated if workspace allocation failed
   subroutine lpb_op2_assemble(self, a, error)
      !> Operator
      class(lpb_op2), intent(in) :: self
      !> Dense operator matrix
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: stat
      real(wp), allocatable :: tmp1(:, :), tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), &
                               tmp6(:, :), tmp7(:, :), tmp8(:, :), tmp9(:, :), tmp10(:, :)
      integer :: i

      allocate (tmp1(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp2(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp3(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp4(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp5(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp6(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp7(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp8(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp9(self%npt, self%npt), stat=stat)
      if (stat == 0) allocate (tmp10(self%npt, self%npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_op2_assemble] allocation failed")
         return
      end if
      do i = 1, self%npt
         tmp1(:, i) = self%a(i)*self%c3(:, i)
      end do
      call gemm(tmp1, self%c2, tmp2)
      tmp3 = (-0.15915494309189535_wp)*tmp2
      tmp4 = self%c2 + tmp3
      tmp5 = self%c1*tmp4
      do i = 1, self%npt
         tmp6(:, i) = self%a(i)*self%c5(:, i)
      end do
      call gemm(tmp6, self%c6, tmp7, transb="t")
      tmp8 = 0.15915494309189535_wp*tmp7
      tmp9 = self%c5 + tmp8
      tmp10 = self%c4*tmp9
      a = tmp5 + tmp10
   end subroutine lpb_op2_assemble

   !> Form operator 2 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine lpb_op2_assemble_block(self, idx, a, error)
      !> Operator
      class(lpb_op2), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp1(:)
      real(wp), allocatable :: tmp2(:, :), tmp3(:, :), tmp4(:, :), tmp5(:, :), tmp6(:, :), &
                               tmp7(:, :), tmp8(:, :), tmp9(:, :), tmp10(:, :), tmp11(:, :), &
                               tmp12(:, :), tmp13(:, :), tmp14(:, :), tmp15(:, :)
      integer :: i

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[lpb_op2_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp4(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp5(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp6(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp7(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp8(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp9(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp10(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp11(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp12(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp13(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp14(nb, nb), stat=stat)
      if (stat == 0) allocate (tmp15(nb, nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_op2_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%a(idx)
      tmp2 = self%c2(idx, idx)
      tmp3 = self%c3(idx, idx)
      tmp4 = self%c5(idx, idx)
      tmp5 = self%c6(idx, idx)
      do i = 1, nb
         tmp6(:, i) = tmp1(i)*tmp3(:, i)
      end do
      call gemm(tmp6, tmp2, tmp7)
      tmp8 = (-0.15915494309189535_wp)*tmp7
      tmp9 = tmp2 + tmp8
      tmp10 = self%c1*tmp9
      do i = 1, nb
         tmp11(:, i) = tmp1(i)*tmp4(:, i)
      end do
      call gemm(tmp11, tmp5, tmp12, transb="t")
      tmp13 = 0.15915494309189535_wp*tmp12
      tmp14 = tmp4 + tmp13
      tmp15 = self%c4*tmp14
      a = tmp10 + tmp15
   end subroutine lpb_op2_assemble_block

   !> Apply operator 3, symmetric, so also its transpose
   !>
   !> @param[in]  self   operator
   !> @param[in]  trans  apply the transpose if true; the same for this operator
   !> @param[in]  x      input vector
   !> @param[out] y      result vector
   subroutine lpb_op3_apply(self, trans, x, y)
      !> Operator
      class(lpb_op3), intent(in) :: self
      !> Apply the transpose
      logical, intent(in) :: trans
      !> Input vector
      real(wp), contiguous, intent(in) :: x(:)
      !> Result vector
      real(wp), contiguous, intent(out) :: y(:)

      ! The transpose is the operator itself
      associate (unused1 => trans)
      end associate
      block
         real(wp), allocatable :: tmp1(:), tmp2(:), tmp6(:)
         real(wp) :: tmp3, tmp4, tmp5
         real(wp), allocatable :: tmp7(:), tmp1_p(:)
         integer :: i, j

         allocate (tmp1(self%npt))
         allocate (tmp2(self%npt))
         allocate (tmp6(self%npt))
         do i = 1, self%npt
            tmp3 = 1.0_wp/self%F(i)
            tmp4 = self%xi(i)*tmp3
            tmp5 = 0.7978845608028654_wp*tmp4
            tmp2(i) = tmp5
         end do
         tmp6 = tmp2*x
         tmp1 = tmp6
         block
            real(wp) :: tmp8, tmp9, tmp10, tmp11, tmp12, tmp14, tmp15, tmp18, tmp22, tmp13, tmp16, &
                        tmp17, tmp19, tmp20, tmp21, tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, &
                        tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, &
                        tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, tmp48, &
                        tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57, tmp58, &
                        tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, tmp66, tmp67, tmp68, &
                        tmp69, tmp70, tmp71, tmp72, tmp73, tmp74, tmp75, tmp76, tmp77, tmp78, &
                        tmp79, tmp80, tmp81, tmp82, tmp83, tmp84, tmp85, tmp86, tmp87, tmp88, &
                        tmp89, tmp90, tmp91, tmp92, tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, &
                        tmp99, tmp100, tmp101, tmp102, tmp103, tmp104, tmp105

            !$omp parallel &
            !$omp& private(i, j, tmp7, tmp1_p) &
            !$omp& shared(self, tmp1, x) &
            !$omp& default(private)
            allocate (tmp7(self%npt))
            allocate (tmp1_p(self%npt))
            tmp1_p = 0.0_wp
            !$omp do schedule(static)
            do j = 1, self%npt
               tmp8 = self%xi(j)
               tmp9 = self%r(1, j)
               tmp10 = self%r(2, j)
               tmp11 = self%r(3, j)
               tmp12 = x(j)
               tmp14 = tmp8**(2)
               tmp15 = -tmp9
               tmp18 = -tmp10
               tmp22 = -tmp11
               !$omp simd &
               !$omp& private(tmp13, tmp16, tmp17, tmp19, tmp20, tmp21, tmp23, tmp24) &
               !$omp& private(tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32) &
               !$omp& private(tmp33, tmp34, tmp35)
               do i = 1, j - 1
                  tmp16 = self%r(1, i) + tmp15
                  tmp17 = tmp16**(2)
                  tmp19 = self%r(2, i) + tmp18
                  tmp20 = tmp19**(2)
                  tmp21 = tmp17 + tmp20
                  tmp23 = self%r(3, i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp25 = tmp21 + tmp24
                  tmp26 = tmp14*tmp25
                  tmp27 = self%xi(i)**(2)
                  tmp28 = tmp26*tmp27
                  tmp29 = tmp27 + tmp14
                  tmp30 = (-81.0_wp)*tmp29
                  tmp31 = tmp28 + tmp30
                  tmp13 = 0.5_wp + sign(0.5_wp, tmp31)
                  tmp7(i) = tmp13
                  tmp32 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp31))
                  tmp33 = tmp25 + tmp32
                  tmp34 = 1.0_wp/sqrt(tmp33)
                  tmp35 = tmp12*tmp34
                  tmp1_p(i) = tmp1_p(i) + tmp35*tmp13
               end do
               !$omp simd &
               !$omp& private(tmp13, tmp16, tmp17, tmp19, tmp20, tmp21, tmp23, tmp24) &
               !$omp& private(tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32) &
               !$omp& private(tmp33, tmp34, tmp35)
               do i = j + 1, self%npt
                  tmp16 = self%r(1, i) + tmp15
                  tmp17 = tmp16**(2)
                  tmp19 = self%r(2, i) + tmp18
                  tmp20 = tmp19**(2)
                  tmp21 = tmp17 + tmp20
                  tmp23 = self%r(3, i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp25 = tmp21 + tmp24
                  tmp26 = tmp14*tmp25
                  tmp27 = self%xi(i)**(2)
                  tmp28 = tmp26*tmp27
                  tmp29 = tmp27 + tmp14
                  tmp30 = (-81.0_wp)*tmp29
                  tmp31 = tmp28 + tmp30
                  tmp13 = 0.5_wp + sign(0.5_wp, tmp31)
                  tmp7(i) = tmp13
                  tmp32 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp31))
                  tmp33 = tmp25 + tmp32
                  tmp34 = 1.0_wp/sqrt(tmp33)
                  tmp35 = tmp12*tmp34
                  tmp1_p(i) = tmp1_p(i) + tmp35*tmp13
               end do
               do i = 1, self%npt
                  if (i == j) cycle
                  if (tmp7(i) < 0.5_wp) then
                     tmp36 = self%xi(i)**(2)
                     tmp37 = tmp36 + tmp14
                     tmp38 = 0.25_wp*tmp37
                     tmp39 = self%r(1, i) + tmp15
                     tmp40 = tmp39**(2)
                     tmp41 = self%r(2, i) + tmp18
                     tmp42 = tmp41**(2)
                     tmp43 = tmp40 + tmp42
                     tmp44 = self%r(3, i) + tmp22
                     tmp45 = tmp44**(2)
                     tmp46 = tmp43 + tmp45
                     tmp47 = tmp14*tmp46
                     tmp48 = tmp47*tmp36
                     tmp49 = -tmp48
                     tmp50 = tmp38 + tmp49
                     if (tmp50 >= 0.0_wp) then
                        tmp52 = 1.0_wp/sqrt(tmp37)
                        tmp53 = tmp52*self%xi(i)
                        tmp54 = tmp52**(2)
                        tmp55 = tmp47*tmp54
                        tmp56 = tmp55*tmp36
                        tmp57 = 9.422759064650411e-11_wp*tmp56
                        tmp58 = (-1.2290555301717926e-09_wp) + tmp57
                        tmp59 = tmp58*tmp14
                        tmp60 = tmp59*tmp46
                        tmp61 = tmp60*tmp54
                        tmp62 = tmp61*tmp36
                        tmp63 = 1.4807192815879218e-08_wp + tmp62
                        tmp64 = tmp47*tmp63
                        tmp65 = tmp64*tmp54
                        tmp66 = tmp65*tmp36
                        tmp67 = (-1.6365844691234924e-07_wp) + tmp66
                        tmp68 = tmp56*tmp67
                        tmp69 = 1.6462114365889246e-06_wp + tmp68
                        tmp70 = tmp47*tmp69
                        tmp71 = tmp70*tmp54
                        tmp72 = tmp71*tmp36
                        tmp73 = (-1.492565035840625e-05_wp) + tmp72
                        tmp74 = tmp47*tmp73
                        tmp75 = tmp74*tmp54
                        tmp76 = tmp75*tmp36
                        tmp77 = 0.00012055332981789664_wp + tmp76
                        tmp78 = tmp55*tmp77
                        tmp79 = tmp78*tmp36
                        tmp80 = (-0.0008548327023450852_wp) + tmp79
                        tmp81 = tmp47*tmp80
                        tmp82 = tmp81*tmp54
                        tmp83 = tmp82*tmp36
                        tmp84 = 0.005223977625442188_wp + tmp83
                        tmp85 = tmp56*tmp84
                        tmp86 = (-0.026866170645131252_wp) + tmp85
                        tmp87 = tmp47*tmp86
                        tmp88 = tmp87*tmp54
                        tmp89 = tmp88*tmp36
                        tmp90 = 0.11283791670955126_wp + tmp89
                        tmp91 = tmp56*tmp90
                        tmp92 = (-0.37612638903183754_wp) + tmp91
                        tmp93 = tmp47*tmp92
                        tmp94 = tmp93*tmp54
                        tmp95 = tmp94*tmp36
                        tmp96 = 1.1283791670955126_wp + tmp95
                        tmp97 = tmp53*tmp96
                        tmp51 = tmp97*tmp8
                     else
                        tmp98 = 1.0_wp/sqrt(tmp46)
                        tmp99 = 1.0_wp/sqrt(tmp37)
                        tmp100 = tmp99*self%xi(i)
                        tmp101 = sqrt(tmp46)
                        tmp102 = tmp100*tmp101
                        tmp103 = tmp102*tmp8
                        tmp104 = erf(tmp103)
                        tmp51 = tmp98*tmp104
                     end if
                     tmp105 = tmp51*tmp12
                     tmp1_p(i) = tmp1_p(i) + tmp105
                  end if
               end do
            end do
            !$omp end do
            !$omp critical (pcmgen_sum)
            tmp1 = tmp1 + tmp1_p
            !$omp end critical (pcmgen_sum)
            deallocate (tmp7)
            deallocate (tmp1_p)
            !$omp end parallel
         end block
         y = tmp1
      end block
   end subroutine lpb_op3_apply

   !> Form operator 3 of the points idx alone
   !>
   !> - Its expression with every kernel, diagonal and point vector restricted
   !>   to idx: the principal submatrix unless the operator has matrix products
   !> - Points in the order of idx
   !>
   !> @param[in]  self  operator
   !> @param[in]  idx   point indices (nb distinct values in 1..npoint)
   !> @param[out] a     matrix of shape (nb, nb)
   !> @param[out] error  error handling; allocated on a wrong shape or failed allocation
   subroutine lpb_op3_assemble_block(self, idx, a, error)
      !> Operator
      class(lpb_op3), intent(in) :: self
      !> Point indices
      integer, contiguous, intent(in) :: idx(:)
      !> Operator matrix of the points
      real(wp), contiguous, intent(out) :: a(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: nb
      integer :: stat
      real(wp), allocatable :: tmp2(:), tmp3(:)
      real(wp), allocatable :: tmp1(:, :)
      real(wp) :: tmp140, tmp141, tmp142
      integer :: i, j

      nb = size(idx)
      if (any(shape(a) /= [nb, nb])) then
         call fatal_error(error, "[lpb_op3_assemble_block] a: wrong shape")
         return
      end if
      allocate (tmp1(3, nb), stat=stat)
      if (stat == 0) allocate (tmp2(nb), stat=stat)
      if (stat == 0) allocate (tmp3(nb), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[lpb_op3_assemble_block] allocation failed")
         return
      end if
      tmp1 = self%r(:, idx)
      tmp2 = self%xi(idx)
      tmp3 = self%F(idx)
      block
         real(wp) :: tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, &
                     tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, tmp23, tmp24, tmp25, tmp26, &
                     tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, &
                     tmp38, tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46, tmp47, tmp48, &
                     tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, tmp56, tmp57, tmp58, tmp59, &
                     tmp60, tmp61, tmp62, tmp63, tmp64, tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, &
                     tmp71, tmp72, tmp73, tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, &
                     tmp82, tmp83, tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, tmp92, &
                     tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, tmp101, tmp102, &
                     tmp103
         real(wp) :: tmp104, tmp105, tmp106, tmp107, tmp108, tmp109, tmp110, tmp111, tmp112, &
